package br.com.confirmacao.patient.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.patient.application.PatientService;import br.com.confirmacao.shared.api.PageResponse;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.Pageable;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/patients") public class PatientController{private final PatientService service;private final AuditService audit;public PatientController(PatientService s,AuditService a){service=s;audit=a;}@PostMapping public ResponseEntity<PatientResponse> create(JwtAuthenticationToken j,@Valid@RequestBody CreatePatientRequest q,HttpServletRequest h){var p=service.create(pid(j),q.fullName(),q.birthDate(),q.phone(),q.email(),q.preferredChannel());audit.record(AuditAction.PATIENT_CREATED,"PATIENT",p.getId(),h);return ResponseEntity.status(HttpStatus.CREATED).body(PatientResponse.from(p));}@GetMapping public PageResponse<PatientResponse> all(JwtAuthenticationToken j,@ParameterObject@PageableDefault(size=20,sort="fullName")Pageable p){return PageResponse.from(service.findAll(pid(j),p).map(PatientResponse::from));}@GetMapping("/{id}")public PatientResponse one(JwtAuthenticationToken j,@PathVariable UUID id){return PatientResponse.from(service.findById(pid(j),id));}@PutMapping("/{id}")public PatientResponse update(JwtAuthenticationToken j,@PathVariable UUID id,@Valid@RequestBody UpdatePatientRequest q,HttpServletRequest h){var x=service.update(pid(j),id,q.fullName(),q.birthDate(),q.phone(),q.email(),q.preferredChannel());audit.record(AuditAction.PATIENT_UPDATED,"PATIENT",id,h);return PatientResponse.from(x);}@DeleteMapping("/{id}")public ResponseEntity<Void> off(JwtAuthenticationToken j,@PathVariable UUID id,HttpServletRequest h){service.deactivate(pid(j),id);audit.record(AuditAction.PATIENT_DEACTIVATED,"PATIENT",id,h);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/activate")public ResponseEntity<Void> on(JwtAuthenticationToken j,@PathVariable UUID id){service.activate(pid(j),id);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/consent/grant")public PatientResponse grant(JwtAuthenticationToken j,@PathVariable UUID id){return PatientResponse.from(service.grantConsent(pid(j),id));}@PatchMapping("/{id}/consent/revoke")public PatientResponse revoke(JwtAuthenticationToken j,@PathVariable UUID id){return PatientResponse.from(service.revokeConsent(pid(j),id));}private UUID pid(JwtAuthenticationToken j){return UUID.fromString(j.getToken().getClaimAsString("professional_id"));}}
